data class RestoreLabInvestigationCommand(
    override val editorSessionId: String = "",
    override val operationUuid: String,
    override val patientId: String,
    override val expectedPatientRevision: Long,
    val record: DemoLabInvestigation,
    val sourceDelete: DeleteLabInvestigationCommand,
) : ClinicalCommand {
    override val recordKind = ClinicalRecordKind.LAB_RESTORE
    override val recordId: String get() = record.id

    override fun destination(): AncRoute = AncRoute.Workspace(patientId, WorkspaceSection.LABORATORY)
    override fun savedNotice(): SavedNotice = SavedNotice.LAB_RESTORED

    override fun isStructurallyValid(): Boolean {
        if (!isValidUuid(operationUuid) || patientId.isBlank() || record.id.isBlank()) return false
        if (expectedPatientRevision < 1) return false
        if (!sourceDelete.isStructurallyValid()) return false
        return true
    }

    override fun computeFingerprint(): String = sha256(
        "LAB_RES|$operationUuid|$patientId|$expectedPatientRevision|${sourceDelete.computeFingerprint()}|${canonicalLab(record)}",
    )
}

private fun isValidUuid(raw: String): Boolean = try {
    UUID.fromString(raw)
    true
} catch (_: Exception) {
    false
}

private fun sha256(text: String): String = sha256Hex(text)

package com.sherifradwan.ancnative.storage

object ClinicalDeleteRule {
    fun evaluateRestore(
        receipt: ClinicalCommandReceipt?,
        latestReceipt: ClinicalCommandReceipt?,
        existingRow: Any?,
        cmd: ClinicalCommand,
    ): ClinicalCommandFailure? {
        val (expectedKind, expectedFingerprint, recordContentHash, sourceHash) = when (cmd) {
            is RestoreMedicationCommand -> {
                RestoreSource(
                    ClinicalRecordKind.MEDICATION_DELETE.name,
                    cmd.sourceDelete.computeFingerprint(),
                    medicationContentHash(cmd.record),
                    cmd.sourceDelete.deletedContentHash,
                )
            }
            is RestoreLabInvestigationCommand -> {
                RestoreSource(
                    ClinicalRecordKind.LAB_DELETE.name,
                    cmd.sourceDelete.computeFingerprint(),
                    labContentHash(cmd.record),
                    cmd.sourceDelete.deletedContentHash,
                )
            }
            else -> return ClinicalCommandFailure.INVALID_COMMAND
        }

        if (receipt == null) return ClinicalCommandFailure.RECORD_CONFLICT
        if (receipt.recordKind != expectedKind) return ClinicalCommandFailure.RECORD_CONFLICT
        if (receipt.patientId != cmd.patientId) return ClinicalCommandFailure.RECORD_CONFLICT
        if (receipt.recordId != cmd.recordId) return ClinicalCommandFailure.RECORD_CONFLICT
        if (receipt.fingerprint != expectedFingerprint) return ClinicalCommandFailure.RECORD_CONFLICT
        if (latestReceipt == null || latestReceipt.operationUuid != receipt.operationUuid) {
            return ClinicalCommandFailure.RECORD_CONFLICT
        }
        if (existingRow != null) return ClinicalCommandFailure.RECORD_CONFLICT
        if (recordContentHash != sourceHash) return ClinicalCommandFailure.INVALID_COMMAND

        return null
    }

    private data class RestoreSource(
        val kind: String,
        val fingerprint: String,
        val recordContentHash: String,
        val sourceHash: String,
    )
}

